 const payRows=data.payments.filter(p=>(scope==='all'||p.projectId===scope)&&(paymentFilter==='All payments'||(paymentFilter==='Expenses'?p.direction==='expense':paymentFilter==='Buyer collections'?p.direction==='receipt':p.amount>p.paid))&&(`${p.party} ${p.category} ${p.reference}`).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));
 const buyerRows=data.buyers.filter(b=>(scope==='all'||b.projectId===scope)&&(`${b.name} ${b.unit}`).toLowerCase().includes(search.toLowerCase()));
 const pending=data.payments.filter(p=>p.direction==='expense'&&p.amount>p.paid&&(scope==='all'||p.projectId===scope)).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));
 const open=(m:Modal)=>{if(m&&['upload','payment','buyer'].includes(m.type)&&!data.projects.length){setToast('Create your first project to add documents, payments, or buyers.');m={type:'project'};}setError('');setFormProject(currentProject?.id||data.projects[0]?.id||'');setModal(m);};
