 async function api<T>(path:string,init?:RequestInit):Promise<T>{
  let raw:string;
  if(path==='/api/workspace'&&init?.method==='PUT'){const input=JSON.parse(String(init.body));raw=android().saveWorkspace(JSON.stringify(input.workspace),input.revision);}
  else if(path==='/api/workspace')raw=android().readWorkspace();
  else if(path==='/api/files')raw=android().readFiles();
  else throw new Error('This action is unavailable on this phone.');
  const result=JSON.parse(raw) as T & {error?:string};if(result.error)throw new Error(result.error);return result;
 }
 async function load(){if(!user)return;setLoading(true);setLoadError('');try{const [w,f]=await Promise.all([api<{workspace:Workspace|null;revision:number}>('/api/workspace'),api<{files:StoredFile[]}>('/api/files')]);if(w.workspace){setData(w.workspace);setDemo(false);setRevision(w.revision);}else if(firstLoad.current&&account.authenticated){setModal({type:"workspace"});}firstLoad.current=false;setFiles(f.files);}catch(e){setLoadError((e as Error).message);}finally{setLoading(false);}}
